#!/usr/bin/env python3
"""A shared Markdown notes wiki for a study group, backed by one JSON file on a mount."""
import json
import os
import re
import uuid
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

import bleach
import markdown

DATA_DIR = os.environ.get("DATA_DIR", "/data")
PAGES_FILE = os.path.join(DATA_DIR, "pages.json")
PORT = int(os.environ.get("PORT", "8080"))

SLUG_RE = re.compile(r"^/api/pages/([a-z0-9-]+)$")

ALLOWED_TAGS = [
    "p", "br", "hr", "strong", "em", "del", "code", "pre", "blockquote",
    "ul", "ol", "li", "a", "img", "h1", "h2", "h3", "h4", "h5", "h6",
    "table", "thead", "tbody", "tr", "th", "td",
]
ALLOWED_ATTRS = {"a": ["href", "title"], "img": ["src", "alt", "title"]}


def load():
    try:
        with open(PAGES_FILE) as handle:
            return json.load(handle)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}


def save(pages):
    tmp = PAGES_FILE + ".tmp"
    with open(tmp, "w") as handle:
        json.dump(pages, handle, indent=2)
    os.replace(tmp, PAGES_FILE)


def now():
    return datetime.now(timezone.utc).isoformat()


def slugify(title):
    slug = re.sub(r"[^a-z0-9]+", "-", title.strip().lower()).strip("-")
    return slug or uuid.uuid4().hex[:8]


def render(content):
    html = markdown.markdown(
        content, extensions=["extra", "sane_lists", "nl2br"], output_format="html"
    )
    return bleach.clean(html, tags=ALLOWED_TAGS, attributes=ALLOWED_ATTRS)


