            "content": content,
            "author": author[:40],
            "created_at": existing.get("created_at", now()),
            "updated_at": now(),
        }
        pages[slug] = page
        save(pages)
        return self.send_json(200, self.page_out(slug, page))

    def do_DELETE(self):
        match = SLUG_RE.match(self.path)
        if not match:
            return self.send_json(404, {"error": "not found"})
        slug = match.group(1)
        pages = load()
        if slug not in pages:
            return self.send_json(404, {"error": "page not found"})
