#!/usr/bin/env python3
"""A shared Markdown notes wiki for a study group, backed by one JSON file on a mount."""
import json
import os
import re
import uuid
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

import bleach
import markdown

DATA_DIR = os.environ.get("DATA_DIR", "/data")
PAGES_FILE = os.path.join(DATA_DIR, "pages.json")
PORT = int(os.environ.get("PORT", "8080"))

SLUG_RE = re.compile(r"^/api/pages/([a-z0-9-]+)$")

ALLOWED_TAGS = [
    "p", "br", "hr", "strong", "em", "del", "code", "pre", "blockquote",
    "ul", "ol", "li", "a", "img", "h1", "h2", "h3", "h4", "h5", "h6",
    "table", "thead", "tbody", "tr", "th", "td",
]
ALLOWED_ATTRS = {"a": ["href", "title"], "img": ["src", "alt", "title"]}


def load():
    try:
        with open(PAGES_FILE) as handle:
            return json.load(handle)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}


def save(pages):
    tmp = PAGES_FILE + ".tmp"
    with open(tmp, "w") as handle:
        json.dump(pages, handle, indent=2)
    os.replace(tmp, PAGES_FILE)


def now():
    return datetime.now(timezone.utc).isoformat()


def slugify(title):
    slug = re.sub(r"[^a-z0-9]+", "-", title.strip().lower()).strip("-")
    return slug or uuid.uuid4().hex[:8]


def render(content):
    html = markdown.markdown(
        content, extensions=["extra", "sane_lists", "nl2br"], output_format="html"
    )
    return bleach.clean(html, tags=ALLOWED_TAGS, attributes=ALLOWED_ATTRS)


PAGE = """<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Study Group Wiki</title>
<style>
  :root {
    color-scheme: light dark;
    --accent: #4f46e5;
    --bg: #f6f7fb;
    --card: #ffffff;
    --text: #1f2430;
    --muted: #6b7280;
    --border: #e5e7eb;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: var(--bg);
    color: var(--text);
  }
  header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 24px;
    background: var(--card);
    border-bottom: 1px solid var(--border);
  }
  header h1 { font-size: 1.3rem; margin: 0; cursor: pointer; }
  header .actions { display: flex; gap: 8px; }
  main {
    max-width: 760px;
    margin: 0 auto;
    padding: 24px 16px 80px;
  }
  button, .btn {
    padding: 8px 14px;
    border: none;
    border-radius: 8px;
    background: var(--accent);
    color: white;
    font-size: 0.9rem;
    cursor: pointer;
    text-decoration: none;
    display: inline-block;
  }
  button.secondary, .btn.secondary {
    background: transparent;
    color: var(--muted);
    border: 1px solid var(--border);
  }
  button.danger { background: #dc2626; }
  ul#page-list { list-style: none; margin: 0; padding: 0; }
  ul#page-list li {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 14px 16px;
    margin-bottom: 8px;
    cursor: pointer;
  }
  ul#page-list li:hover { border-color: var(--accent); }
  ul#page-list .title { font-weight: 600; }
  ul#page-list .meta { font-size: 0.8rem; color: var(--muted); margin-top: 2px; }
  .empty { color: var(--muted); text-align: center; padding: 40px 0; }
  #page-view {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 24px;
  }
  #page-view .meta { color: var(--muted); font-size: 0.85rem; margin-bottom: 16px; }
  #page-view .content :first-child { margin-top: 0; }
  #page-view .content pre { background: var(--bg); padding: 10px; border-radius: 6px; overflow-x: auto; }
  #page-view .content code { background: var(--bg); padding: 1px 4px; border-radius: 4px; }
  #page-view .content pre code { background: none; padding: 0; }
  .toolbar { margin-bottom: 16px; display: flex; gap: 8px; }
  #editor-form input[type=text], #editor-form textarea {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid var(--border);
    border-radius: 8px;
    font-size: 1rem;
    margin-bottom: 10px;
    font-family: inherit;
  }
  #editor-form textarea { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; min-height: 320px; resize: vertical; }
  #editor-form .row { display: flex; gap: 10px; }
  #editor-form .row input { flex: 1; }
  [hidden] { display: none !important; }
</style>
</head>
<body>
<header>
  <h1 id="home-link">Study Group Wiki</h1>
  <div class="actions">
    <button id="new-btn">New page</button>
  </div>
</header>
<main>
  <div id="list-view">
    <ul id="page-list"></ul>
    <p class="empty" id="list-empty" hidden>No pages yet. Write the first one!</p>
  </div>

  <div id="page-view" hidden>
    <div class="toolbar">
      <button class="secondary" id="back-btn">&larr; All pages</button>
      <button id="edit-btn">Edit</button>
      <button class="danger" id="delete-btn">Delete</button>
    </div>
    <h2 id="view-title"></h2>
    <p class="meta" id="view-meta"></p>
    <div class="content" id="view-content"></div>
  </div>

  <div id="editor-view" hidden>
    <form id="editor-form">
      <div class="row">
        <input type="text" id="edit-title" placeholder="Page title" required maxlength="120">
        <input type="text" id="edit-author" placeholder="Your name" maxlength="40">
      </div>
      <textarea id="edit-content" placeholder="Write your notes in Markdown..." required></textarea>
      <div class="toolbar">
        <button type="submit">Save</button>
        <button type="button" class="secondary" id="cancel-btn">Cancel</button>
      </div>
    </form>
  </div>
</main>
<script>
const listView = document.getElementById('list-view');
const pageView = document.getElementById('page-view');
const editorView = document.getElementById('editor-view');
const pageList = document.getElementById('page-list');
const listEmpty = document.getElementById('list-empty');
const authorInput = document.getElementById('edit-author');
authorInput.value = localStorage.getItem('wiki-author') || '';

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function showView(view) {
  listView.hidden = view !== 'list';
  pageView.hidden = view !== 'page';
  editorView.hidden = view !== 'editor';
}

function fmtTime(iso) {
  return new Date(iso).toLocaleString();
}

async function loadList() {
  const res = await fetch('/api/pages');
  const data = await res.json();
  renderList(data.pages);
}

function renderList(pages) {
  pageList.innerHTML = '';
  listEmpty.hidden = pages.length !== 0;
  for (const p of pages) {
    const li = document.createElement('li');
    li.innerHTML = `<div class="title">${escapeHtml(p.title)}</div>
      <div class="meta">by ${escapeHtml(p.author || 'anonymous')} &middot; updated ${fmtTime(p.updated_at)}</div>`;
    li.addEventListener('click', () => location.hash = `#/page/${p.slug}`);
    pageList.appendChild(li);
  }
}

let currentSlug = null;

async function loadPage(slug) {
  const res = await fetch(`/api/pages/${slug}`);
  if (!res.ok) { location.hash = ''; return; }
  const page = await res.json();
  currentSlug = page.slug;
  document.getElementById('view-title').textContent = page.title;
  document.getElementById('view-meta').textContent =
    `by ${page.author || 'anonymous'} · updated ${fmtTime(page.updated_at)}`;
  document.getElementById('view-content').innerHTML = page.content_html;
  showView('page');
}

async function loadEditor(slug) {
  document.getElementById('edit-title').value = '';
  document.getElementById('edit-content').value = '';
  if (slug) {
    const res = await fetch(`/api/pages/${slug}`);
    if (res.ok) {
      const page = await res.json();
      document.getElementById('edit-title').value = page.title;
      document.getElementById('edit-content').value = page.content;
    }
  }
  currentSlug = slug || null;
  showView('editor');
}

document.getElementById('editor-form').addEventListener('submit', async (e) => {
  e.preventDefault();
  const title = document.getElementById('edit-title').value.trim();
  const content = document.getElementById('edit-content').value;
  const author = authorInput.value.trim();
  if (!title || !content.trim()) return;
  localStorage.setItem('wiki-author', author);
  const url = currentSlug ? `/api/pages/${currentSlug}` : '/api/pages';
  const res = await fetch(url, {
    method: currentSlug ? 'PUT' : 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title, content, author }),
  });
  const page = await res.json();
  location.hash = `#/page/${page.slug}`;
});

document.getElementById('new-btn').addEventListener('click', () => location.hash = '#/new');
document.getElementById('home-link').addEventListener('click', () => location.hash = '');
document.getElementById('back-btn').addEventListener('click', () => location.hash = '');
document.getElementById('cancel-btn').addEventListener('click', () => {
  location.hash = currentSlug ? `#/page/${currentSlug}` : '';
});
document.getElementById('edit-btn').addEventListener('click', () => location.hash = `#/edit/${currentSlug}`);
document.getElementById('delete-btn').addEventListener('click', async () => {
  if (!currentSlug) return;
  if (!confirm('Delete this page? This cannot be undone.')) return;
  await fetch(`/api/pages/${currentSlug}`, { method: 'DELETE' });
  location.hash = '';
});

async function route() {
  const hash = location.hash;
  let m;
  if ((m = hash.match(/^#\/page\/([a-z0-9-]+)$/))) {
    await loadPage(m[1]);
  } else if ((m = hash.match(/^#\/edit\/([a-z0-9-]+)$/))) {
    await loadEditor(m[1]);
  } else if (hash === '#/new') {
    await loadEditor(null);
  } else {
    showView('list');
    await loadList();
  }
}

window.addEventListener('hashchange', route);
route();
</script>
</body>
</html>
"""


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        print("%s %s" % (self.command, self.path), flush=True)

    def send_json(self, status, payload):
        raw = json.dumps(payload).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)

    def send_html(self, status, body):
        raw = body.encode()
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)

    def read_json(self):
        length = int(self.headers.get("Content-Length") or 0)
        if length == 0:
            return {}
        try:
            return json.loads(self.rfile.read(length))
        except json.JSONDecodeError:
            return None

    def page_out(self, slug, page):
        out = dict(page)
        out["slug"] = slug
        out["content_html"] = render(page["content"])
        return out

    def do_GET(self):
        if self.path == "/healthz":
            return self.send_html(200, "ok")
        if self.path in ("/", "/index.html"):
            return self.send_html(200, PAGE)
        if self.path == "/api/pages":
            pages = load()
            summaries = [
                {"slug": slug, "title": p["title"], "author": p.get("author", ""), "updated_at": p["updated_at"]}
                for slug, p in pages.items()
            ]
            summaries.sort(key=lambda p: p["updated_at"], reverse=True)
            return self.send_json(200, {"pages": summaries})
        match = SLUG_RE.match(self.path)
        if match:
            pages = load()
            page = pages.get(match.group(1))
            if page is None:
                return self.send_json(404, {"error": "page not found"})
            return self.send_json(200, self.page_out(match.group(1), page))
        return self.send_json(404, {"error": "not found"})

    def do_POST(self):
        if self.path == "/api/pages":
            body = self.read_json()
            if body is None:
                return self.send_json(400, {"error": "body is not JSON"})
            title = str(body.get("title", "")).strip()
            content = str(body.get("content", ""))
            if not title or not content.strip():
                return self.send_json(400, {"error": "title and content are required"})
            author = str(body.get("author", "")).strip() or "anonymous"
            pages = load()
            slug = slugify(title)
            base_slug = slug
            n = 2
            while slug in pages:
                slug = f"{base_slug}-{n}"
                n += 1
            timestamp = now()
            page = {
                "title": title[:120],
                "content": content,
                "author": author[:40],
                "created_at": timestamp,
                "updated_at": timestamp,
            }
            pages[slug] = page
            save(pages)
            return self.send_json(201, self.page_out(slug, page))
        return self.send_json(404, {"error": "not found"})

    def do_PUT(self):
        match = SLUG_RE.match(self.path)
        if not match:
            return self.send_json(404, {"error": "not found"})
        slug = match.group(1)
        pages = load()
        existing = pages.get(slug)
        if existing is None:
            return self.send_json(404, {"error": "page not found"})
        body = self.read_json()
        if body is None:
            return self.send_json(400, {"error": "body is not JSON"})
        title = str(body.get("title", existing["title"])).strip()
        content = str(body.get("content", existing["content"]))
        if not title or not content.strip():
            return self.send_json(400, {"error": "title and content are required"})
        author = str(body.get("author", "")).strip() or existing.get("author", "anonymous")
        page = {
            "title": title[:120],
            "content": content,
            "author": author[:40],
            "created_at": existing.get("created_at", now()),
            "updated_at": now(),
        }
        pages[slug] = page
        save(pages)
        return self.send_json(200, self.page_out(slug, page))

    def do_DELETE(self):
        match = SLUG_RE.match(self.path)
        if not match:
            return self.send_json(404, {"error": "not found"})
        slug = match.group(1)
        pages = load()
        if slug not in pages:
            return self.send_json(404, {"error": "page not found"})
        del pages[slug]
        save(pages)
        return self.send_json(200, {"ok": True})


if __name__ == "__main__":
    os.makedirs(DATA_DIR, exist_ok=True)
    ThreadingHTTPServer(("0.0.0.0", PORT), Handler).serve_forever()

